-- ENG-070 / ORG-061. Synthetic rollback-only announcements authorization proofs.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir ../support/registration-fixtures.psql

select ok(not exists(select 1 from pg_class c where c.relnamespace='msrc_announcements'::regnamespace and c.relkind='r' and not(c.relrowsecurity and c.relforcerowsecurity)),'Every announcement table forces RLS');
select ok(not exists(select 1 from pg_policies where schemaname='msrc_announcements'),'No permissive client policies');
select ok(not exists(select 1 from(values('anon'),('authenticated'),('service_role')) r(name) where has_schema_privilege(name,'msrc_announcements','USAGE')),'API roles have no private schema access');
select ok(not exists(select 1 from pg_class c cross join(values('anon'),('authenticated'),('service_role')) r(name) where c.relnamespace='msrc_announcements'::regnamespace and c.relkind='r' and has_table_privilege(name,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')),'No API role has direct table access');
select ok(not exists(select 1 from pg_proc p where p.pronamespace='msrc_announcements'::regnamespace and p.prosecdef and not coalesce(p.proconfig @>array['search_path=""'],false)),'Private definer functions have empty search paths');
select ok(not exists(select 1 from pg_proc p cross join lateral aclexplode(p.proacl) a where p.pronamespace='public'::regnamespace and p.proname in('msrc_participant_announcements','msrc_announcements_maintenance') and a.grantee in(0,'anon'::regrole,'authenticated'::regrole)),'Participant and maintenance RPCs are server-only');
select is((select count(*) from msrc_announcements.announcements),0::bigint,'No announcements seeded');
select ok((select not delivery_enabled and not sweeps_enabled and daily_cap=0 from msrc_outbox.settings),'Delivery switches and zero cap remain closed');
set local role anon;
select throws_ok($$select public.msrc_staff_announcements_list('synthetic-announcements')$$,'42501',null,'Anonymous staff RPC is denied');
select throws_ok($$select * from msrc_announcements.inbox$$,'42501',null,'Anonymous inbox direct access is denied');
reset role;
set local role authenticated;
select throws_ok($$select public.msrc_participant_announcements('synthetic-announcements','{}'::jsonb)$$,'42501',null,'Authenticated callers cannot forward forged participant claims');
select throws_ok($$select * from msrc_announcements.recipients$$,'42501',null,'Authenticated direct snapshot access is denied');
reset role;
select ok(msrc_announcements.text_valid('A < B & C > D',false),'Plain mathematical text is valid');
select ok(not msrc_announcements.text_valid(E'Injected\r\nSubject',true),'Subject header controls are rejected');
select ok(not msrc_announcements.text_valid('<img src=x onerror=alert(1)>',false),'Raw HTML is rejected');
select ok(not msrc_announcements.text_valid(repeat('x',3501),false),'Body technical limit enforced');
select ok(msrc_announcements.text_valid(repeat(U&'\+01F600',1750),false),'Astral body at 3500 UTF-16 units validates');
select ok(not msrc_announcements.text_valid(repeat(U&'\+01F600',1751),false),'Astral body above 3500 UTF-16 units rejected like renderer');
select ok(msrc_announcements.text_valid(repeat(U&'\+01F600',45),true),'Astral subject at 90 UTF-16 units validates');
select ok(not msrc_announcements.text_valid(repeat(U&'\+01F600',46),true),'Astral subject above 90 UTF-16 units rejected like renderer');
select ok(not msrc_announcements.text_valid(U&'\00A0\2003\FEFF',false),'ECMAScript whitespace-only body rejected like renderer trim');
select ok(msrc_announcements.text_valid(E'Paragraph one\n\nParagraph two',false),'Paragraphs are preserved');
select ok(msrc_announcements.message_valid('announcement',1,'en','synthetic@example.invalid','{"subject_en":"Synthetic notice","subject_ar":"إعلان تجريبي","body_en":"Synthetic text","body_ar":"نص تجريبي"}'::jsonb),'Exact bilingual plain-text payload validates');
select ok(not msrc_announcements.message_valid('announcement',1,'en','synthetic@example.invalid','{"subject_en":"Synthetic notice","subject_ar":"إعلان تجريبي","body_en":"Synthetic text","body_ar":"نص تجريبي","html":"forbidden"}'::jsonb),'Extra provider payload keys rejected');
select ok(not msrc_announcements.message_valid('announcement',1,'ar','synthetic@example.invalid','{"subject_en":"Synthetic notice","subject_ar":"إعلان تجريبي","body_en":"Synthetic text","body_ar":"نص تجريبي"}'::jsonb),'Bilingual composition uses fixed en envelope');
select throws_ok($$select public.msrc_outbox_enqueue('synthetic-forged-announcement','announcement',1,'en','synthetic@example.invalid','{}'::jsonb)$$,'22023',null,'Generic producer cannot bypass announcement authority');

update msrc_participant.policy set enabled=true,privacy_version='synthetic-registration-notice',email_daily_limit=1000;
update msrc_participant.retention_policy set enabled=true;
update msrc_staff.policy set enabled=true,email_daily_limit=1000;
select pg_temp.registration_settings('synthetic-announcements');
do $$declare n integer;begin for n in 9801..9806 loop perform pg_temp.registration_fixture(n,'synthetic-announcements');end loop;end$$;
select pg_temp.registration_fixture(9807,'synthetic-announcements',false);
select pg_temp.registration_staff_fixture(9810,'synthetic-announcements');
select pg_temp.registration_staff_fixture(9811,'synthetic-announcements','registrationWorkshopAdministrator');
select pg_temp.registration_staff_fixture(9812,'synthetic-announcements','abstractReviewer');
select pg_temp.registration_staff_fixture(9813,'synthetic-announcements','checkInStaff');
select pg_temp.registration_staff_fixture(9814,'synthetic-announcements','contentMediaEditor');
-- Native sessions exist in earlier statements before observe_context RPCs.
do $$declare n integer;begin for n in 9801..9805 loop perform pg_temp.registration_submit('synthetic-announcements',n,md5(n::text)||md5(n::text));end loop;end$$;
update msrc_registration.requests set status=case actor_id when pg_temp.registration_actor(9802) then 'approved' when pg_temp.registration_actor(9803) then 'confirmed' when pg_temp.registration_actor(9804) then 'waitlisted' when pg_temp.registration_actor(9805) then 'offered' else 'pending_approval' end,
 offer_expires_at=case when actor_id=pg_temp.registration_actor(9805) then clock_timestamp()+interval '1 day' end where edition_key='synthetic-announcements';
insert into msrc_abstracts.settings(edition_key,version,configuration) values('synthetic-announcements',1,'{}'::jsonb);
insert into msrc_abstracts.submissions(edition_key,actor_id,version,document,status,word_count,finalized_at) values
 ('synthetic-announcements',pg_temp.registration_actor(9801),1,'{}'::jsonb,'submitted',1,clock_timestamp()),
 ('synthetic-announcements',pg_temp.registration_actor(9802),1,'{}'::jsonb,'accepted',1,clock_timestamp()),
 ('synthetic-announcements',pg_temp.registration_actor(9806),1,'{}'::jsonb,'draft',1,null);
select is((select count(*) from msrc_announcements.audience('synthetic-announcements') where segment='verified_participants'),6::bigint,'Only verified participant-only accounts in participant segment');
select is((select count(*) from msrc_announcements.audience('synthetic-announcements') where segment='registration_pending'),1::bigint,'Pending uses real pending_approval status');
select is((select count(*) from msrc_announcements.audience('synthetic-announcements') where segment='registration_approved'),1::bigint,'Approved segment uses existing request state');
select is((select count(*) from msrc_announcements.audience('synthetic-announcements') where segment='registration_confirmed'),1::bigint,'Confirmed segment uses existing request state');
select is((select count(*) from msrc_announcements.audience('synthetic-announcements') where segment='registration_waitlisted'),1::bigint,'Waitlisted segment uses existing request state');
select is((select count(*) from msrc_announcements.audience('synthetic-announcements') where segment='registration_offered'),1::bigint,'Offered segment uses existing request state');
select is((select count(*) from msrc_announcements.audience('synthetic-announcements') where segment='abstract_submitters'),2::bigint,'Finalized submitters excludes drafts');
select is((select count(*) from msrc_announcements.audience('synthetic-announcements') where segment='accepted_presenters'),1::bigint,'Accepted presenters require published accepted state');
select is((select count(*) from msrc_announcements.audience('synthetic-announcements') where segment='reviewers'),1::bigint,'Reviewers use active actual reviewer grants');
select is((select count(*) from msrc_announcements.audience('synthetic-announcements') where segment='checkin_staff'),1::bigint,'Check-in segment uses actual grants');
select is((select count(*) from msrc_announcements.audience('synthetic-announcements') where segment='active_staff'),5::bigint,'Staff segment deduplicates current account grants');
update msrc_authorization.account_access set state='suspended' where actor_id=pg_temp.registration_actor(9806);
select is((select count(*) from msrc_announcements.audience('synthetic-announcements') where segment='verified_participants'),5::bigint,'Suspended account excluded at send-time source');
update msrc_authorization.account_access set state='active' where actor_id=pg_temp.registration_actor(9806);

create function pg_temp.announcement_input(selected text[] default array['registration_pending','abstract_submitters']) returns jsonb language sql immutable as $$
 select jsonb_build_object('expectedVersion',0,'subjectEn','Synthetic announcement','subjectAr','إعلان تجريبي','bodyEn',E'Synthetic paragraph one\n\nSynthetic paragraph two','bodyAr','نص تجريبي','segments',selected);$$;
create temporary table announcement_results(key text primary key,value jsonb);
select set_config('request.jwt.claims',pg_temp.registration_claims(9811)::text,true);
select is(public.msrc_staff_announcements_list('synthetic-announcements')->>'state','denied','Ordinary staff cannot list announcements');
select is(public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input())->>'state','denied','Ordinary staff cannot create announcement');
select is(public.msrc_staff_announcement_preview('synthetic-announcements',gen_random_uuid(),1)->>'state','denied','Ordinary staff cannot preview');
select is(public.msrc_staff_announcement_send('synthetic-announcements',gen_random_uuid(),1,repeat('a',64),gen_random_uuid())->>'state','denied','Ordinary staff cannot send');
select is(public.msrc_staff_announcement_cancel('synthetic-announcements',gen_random_uuid(),1,gen_random_uuid())->>'state','denied','Ordinary staff cannot cancel');
select set_config('request.jwt.claims',pg_temp.registration_claims(9810)::text,true);
select set_config('synthetic.announcement_admin_claims',current_setting('request.jwt.claims'),true);
select is(public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input()||'{"html":"no"}'::jsonb)->>'state','invalid','Unknown input keys rejected');
select is(public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input()||'{"bodyEn":123}'::jsonb)->>'state','invalid','String fields cannot be numbers');
select is(public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input(array['made_up_segment']))->>'state','invalid','Invented segment rejected');
select is(public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input(array['active_staff','active_staff']))->>'state','invalid','Duplicate audience selection rejected');
insert into announcement_results values('one',public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input()));
select is((select value->>'state' from announcement_results where key='one'),'updated','Exact-session Super Admin may create');
create function pg_temp.announcement_id(key_name text) returns uuid language sql stable as $$select (value#>>'{announcement,id}')::uuid from announcement_results where key=key_name;$$;
select is(public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input()||jsonb_build_object('id',pg_temp.announcement_id('one'),'expectedVersion',0))->>'state','conflict','Stale optimistic version cannot overwrite draft');
insert into announcement_results values('preview',public.msrc_staff_announcement_preview('synthetic-announcements',pg_temp.announcement_id('one'),1));
select is((select value#>>'{preview,total}' from announcement_results where key='preview'),'2','Overlapping pending and abstract segments deduplicate participants');
select ok((select value#>'{preview,segments}' @> '[{"segment":"abstract_submitters","count":2},{"segment":"registration_pending","count":1}]'::jsonb from announcement_results where key='preview'),'Preview reports per-segment counts');
select ok((select (value#>'{preview,samples}')::text !~ 'registration-[0-9]+' from announcement_results where key='preview'),'Preview addresses are masked');
select ok((select not(value->'preview'?'recipients') from announcement_results where key='preview'),'Preview never projects raw recipient snapshot');
select is(public.msrc_staff_announcement_send('synthetic-announcements',pg_temp.announcement_id('one'),1,repeat('a',64),'e7900000-0000-4000-8000-000000009801')->>'state','conflict','Arbitrary preview token cannot send');
select is((select count(*) from msrc_announcements.recipients),0::bigint,'Failed preview creates no snapshot');
update msrc_registration.requests set status='pending_approval' where actor_id=pg_temp.registration_actor(9804);
select is(public.msrc_staff_announcement_send('synthetic-announcements',pg_temp.announcement_id('one'),1,(select value#>>'{preview,previewToken}' from announcement_results where key='preview'),'e7900000-0000-4000-8000-000000009801')->>'state','conflict','Live recipient changes require a new preview');
update msrc_registration.requests set status='waitlisted' where actor_id=pg_temp.registration_actor(9804);
insert into announcement_results values('send',public.msrc_staff_announcement_send('synthetic-announcements',pg_temp.announcement_id('one'),1,(select value#>>'{preview,previewToken}' from announcement_results where key='preview'),'e7900000-0000-4000-8000-000000009801'));
select is((select value->>'state' from announcement_results where key='send'),'updated','Reviewed count publishes inbox and held outbox atomically');
select is((select count(*) from msrc_announcements.recipients),2::bigint,'One immutable recipient row per account');
select is((select count(*) from msrc_announcements.inbox),2::bigint,'One inbox row per recipient');
select is((select count(*) from msrc_outbox.messages where template_key='announcement'),2::bigint,'One outbox job per distinct recipient');
select ok(not exists(select 1 from msrc_outbox.messages where template_key='announcement' and not delivery_hold),'Every DRAFT announcement job is held');
select is(public.msrc_staff_announcement_send('synthetic-announcements',pg_temp.announcement_id('one'),1,(select value#>>'{preview,previewToken}' from announcement_results where key='preview'),'e7900000-0000-4000-8000-000000009801')->>'state','updated','Same operation retry succeeds idempotently');
select is((select count(*) from msrc_outbox.messages where template_key='announcement'),2::bigint,'Retry creates no duplicate messages');
update msrc_outbox.messages set status='failed_retryable' where id=(select outbox_id from msrc_announcements.recipients where announcement_id=pg_temp.announcement_id('one') order by actor_id limit 1);
select is((select (msrc_announcements.projection(a)->>'failedCount')::integer from msrc_announcements.announcements a where a.id=pg_temp.announcement_id('one')),1,'History includes retryable delivery failures');
update msrc_outbox.messages set status='failed_permanent',completed_at=clock_timestamp() where id=(select outbox_id from msrc_announcements.recipients where announcement_id=pg_temp.announcement_id('one') order by actor_id limit 1);
select is((select (msrc_announcements.projection(a)->>'failedCount')::integer from msrc_announcements.announcements a where a.id=pg_temp.announcement_id('one')),1,'History includes permanent delivery failures');
update msrc_outbox.messages set status='queued',completed_at=null where template_key='announcement';
select is(public.msrc_staff_announcement_send('synthetic-announcements',pg_temp.announcement_id('one'),1,repeat('a',64),'e7900000-0000-4000-8000-000000009801')->>'state','conflict','Same operation with changed input conflicts');
select is(public.msrc_staff_announcement_send('synthetic-announcements',pg_temp.announcement_id('one'),1,(select value#>>'{preview,previewToken}' from announcement_results where key='preview'),gen_random_uuid())->>'state','conflict','Different operation cannot double-send sent version');
select throws_ok($$update msrc_announcements.recipients set email='changed@example.invalid'$$,'55000',null,'Recipient snapshot cannot be rewritten');
select throws_ok($$delete from msrc_announcements.recipients$$,'55000',null,'Recipient snapshot cannot be deleted');
select throws_ok($$update msrc_announcements.announcements set body_en='Changed after send' where id=pg_temp.announcement_id('one')$$,'55000',null,'Published inbox content cannot be rewritten');
select throws_ok($$update msrc_outbox.messages set delivery_hold=false where template_key='announcement'$$,'23514',null,'Draft email delivery cannot be unlocked accidentally');
select is(jsonb_array_length(public.msrc_participant_announcements('synthetic-announcements',pg_temp.registration_claims(9801))->'announcements'),1,'Recipient sees own inbox');
select is(jsonb_array_length(public.msrc_participant_announcements('synthetic-announcements',pg_temp.registration_claims(9803))->'announcements'),0,'Nonrecipient sees no foreign inbox');
select is(public.msrc_participant_announcements('synthetic-announcements',pg_temp.registration_claims(9803),pg_temp.announcement_id('one'),true)->>'state','denied','Nonrecipient cannot mark another inbox read');
select is(public.msrc_participant_announcements('synthetic-announcements','{}'::jsonb)->>'state','denied','Malformed forwarded session denied');
select is(public.msrc_participant_announcements('synthetic-announcements',pg_temp.registration_claims(9807))->>'state','denied','Never-verified account denied');
select ok(public.msrc_participant_announcements('synthetic-announcements',pg_temp.registration_claims(9801),pg_temp.announcement_id('one'),true)#>>'{announcements,0,readAt}' is not null,'Owned read state retained');
select ok((select read_at is null from msrc_announcements.inbox where actor_id=pg_temp.registration_actor(9802)),'Mark read cannot change another recipient state');
select is(current_setting('request.jwt.claims'),current_setting('synthetic.announcement_admin_claims'),'Forwarded participant calls restore calling claims');
select is(public.msrc_announcements_maintenance('synthetic-announcements')->>'state','closed','Maintenance stays closed while sweeps off');
update msrc_outbox.settings set delivery_enabled=true,daily_cap=1;
update msrc_outbox.messages set delivery_hold=true where template_key<>'announcement';
select is(public.msrc_outbox_claim(gen_random_uuid(),10,1),'[]'::jsonb,'Held announcement templates cannot acquire delivery lease');
update msrc_outbox.settings set delivery_enabled=false,daily_cap=0,sweeps_enabled=true;

-- Scheduled execution recomputes live data, with no second scheduler or emails.
insert into announcement_results values('scheduled',public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input(array['registration_waitlisted'])));
insert into announcement_results values('schedulePreview',public.msrc_staff_announcement_preview('synthetic-announcements',pg_temp.announcement_id('scheduled'),1));
select is(public.msrc_staff_announcement_send('synthetic-announcements',pg_temp.announcement_id('scheduled'),1,(select value#>>'{preview,previewToken}' from announcement_results where key='schedulePreview'),gen_random_uuid(),clock_timestamp()+interval '1 hour')#>>'{announcement,state}','scheduled','Schedule stores explicit SA action');
select is((select count(*) from msrc_announcements.recipients where announcement_id=pg_temp.announcement_id('scheduled')),0::bigint,'Scheduling does not freeze recipients early');
update msrc_announcements.announcements set scheduled_at=clock_timestamp()-interval '1 second' where id=pg_temp.announcement_id('scheduled');
update msrc_registration.requests set status='pending_approval' where actor_id=pg_temp.registration_actor(9804);
select is(public.msrc_announcements_maintenance('synthetic-announcements')->>'needsReview','1','Changed due-time audience fails closed');
select is((select last_error from msrc_announcements.announcements where id=pg_temp.announcement_id('scheduled')),'audience_changed','Stale schedule explains review requirement');
select is((select state from msrc_announcements.announcements where id=pg_temp.announcement_id('scheduled')),'draft','Stale schedule returns to editable draft');
select is((select count(*) from msrc_announcements.recipients where announcement_id=pg_temp.announcement_id('scheduled')),0::bigint,'Stale schedule publishes no inbox or outbox');
insert into announcement_results values('due',public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input(array['registration_confirmed'])));
insert into announcement_results values('duePreview',public.msrc_staff_announcement_preview('synthetic-announcements',pg_temp.announcement_id('due'),1));
select is(public.msrc_staff_announcement_send('synthetic-announcements',pg_temp.announcement_id('due'),1,(select value#>>'{preview,previewToken}' from announcement_results where key='duePreview'),gen_random_uuid(),clock_timestamp()+interval '1 hour')->>'state','updated','Unchanged audience scheduled');
update msrc_announcements.announcements set scheduled_at=clock_timestamp()-interval '1 second' where id=pg_temp.announcement_id('due');
select is(public.msrc_announcements_maintenance('synthetic-announcements')->>'started','1','Unchanged due-time audience enqueues once');
select is(public.msrc_announcements_maintenance('synthetic-announcements')->>'started','0','Repeated maintenance does not republish');
select is((select count(*) from msrc_announcements.recipients where announcement_id=pg_temp.announcement_id('due')),1::bigint,'Due snapshot freezes actual account once');
insert into announcement_results values('editScheduled',public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input(array['registration_confirmed'])));
insert into announcement_results values('editScheduledPreview',public.msrc_staff_announcement_preview('synthetic-announcements',pg_temp.announcement_id('editScheduled'),1));
select is(public.msrc_staff_announcement_send('synthetic-announcements',pg_temp.announcement_id('editScheduled'),1,(select value#>>'{preview,previewToken}' from announcement_results where key='editScheduledPreview'),gen_random_uuid(),clock_timestamp()+interval '1 hour')#>>'{announcement,state}','scheduled','Editable schedule is authorized explicitly');
select is(public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input(array['registration_confirmed'])||jsonb_build_object('id',pg_temp.announcement_id('editScheduled'),'expectedVersion',2,'bodyEn','Edited synthetic body'))#>>'{announcement,state}','draft','Editing a scheduled announcement returns it to draft');
select ok((select scheduled_at is null and preview_token is null and authorized_by is null and authorized_session is null and version=3 from msrc_announcements.announcements where id=pg_temp.announcement_id('editScheduled')),'Scheduled edit clears prior schedule and send authorization');
select is(public.msrc_staff_announcement_send('synthetic-announcements',pg_temp.announcement_id('editScheduled'),3,(select value#>>'{preview,previewToken}' from announcement_results where key='editScheduledPreview'),gen_random_uuid())->>'state','conflict','Edited schedule requires a fresh count preview');
insert into announcement_results values('cancel',public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input(array['active_staff'])));
select is(public.msrc_staff_announcement_cancel('synthetic-announcements',pg_temp.announcement_id('cancel'),1,'e7900000-0000-4000-8000-000000009899')#>>'{announcement,state}','cancelled','SA can cancel unissued draft');
select is(public.msrc_staff_announcement_cancel('synthetic-announcements',pg_temp.announcement_id('cancel'),1,'e7900000-0000-4000-8000-000000009899')->>'state','updated','Cancel retry is idempotent');
select is(public.msrc_staff_announcement_cancel('synthetic-announcements',pg_temp.announcement_id('one'),2,gen_random_uuid())->>'state','conflict','Published inbox cannot be cancelled or removed');
select is((select count(*) from msrc_announcements.audit where event='enqueued'),2::bigint,'Every send has immutable audit evidence');
select throws_ok($$delete from msrc_announcements.audit$$,'55000',null,'Audit history cannot be deleted');
-- A durable scheduled authorization loses effect when its author loses access.
select pg_temp.registration_staff_fixture(9815,'synthetic-announcements');
select pg_temp.registration_staff_fixture(9816,'synthetic-announcements');
select set_config('request.jwt.claims',pg_temp.registration_claims(9815)::text,true);
insert into announcement_results values('revokedAuthor',public.msrc_staff_announcement_save('synthetic-announcements',pg_temp.announcement_input(array['registration_confirmed'])));
insert into announcement_results values('revokedAuthorPreview',public.msrc_staff_announcement_preview('synthetic-announcements',pg_temp.announcement_id('revokedAuthor'),1));
select is(public.msrc_staff_announcement_send('synthetic-announcements',pg_temp.announcement_id('revokedAuthor'),1,(select value#>>'{preview,previewToken}' from announcement_results where key='revokedAuthorPreview'),gen_random_uuid(),clock_timestamp()+interval '1 hour')->>'state','updated','Assured second Super Admin may schedule');
select set_config('request.jwt.claims',current_setting('synthetic.announcement_admin_claims'),true);
update msrc_announcements.announcements set scheduled_at=clock_timestamp()-interval '1 second' where id=pg_temp.announcement_id('revokedAuthor');
update msrc_authorization.account_access set state='suspended' where actor_id=pg_temp.registration_actor(9815);
select is(public.msrc_announcements_maintenance('synthetic-announcements')->>'needsReview','1','Scheduled author suspension blocks due-time publication');
select is((select last_error from msrc_announcements.announcements where id=pg_temp.announcement_id('revokedAuthor')),'author_no_longer_authorized','Blocked schedule records author authority cause');
select is((select count(*) from msrc_announcements.recipients where announcement_id=pg_temp.announcement_id('revokedAuthor')),0::bigint,'Revoked author schedule freezes no recipients');
select ok(not exists(select 1 from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in('msrc_staff_announcements_list','msrc_staff_announcement_save','msrc_staff_announcement_preview','msrc_staff_announcement_send','msrc_staff_announcement_cancel','msrc_participant_announcements','msrc_announcements_maintenance') and position('perform msrc_announcements.guard()' in p.prosrc)=0),'Every public entrypoint invokes isolation guard before authority work');
select pg_temp.registration_fixture(9891,'synthetic-announcements');
select ok(exists(select 1 from msrc_announcements.audience('synthetic-announcements') where segment='verified_participants' and actor_id=pg_temp.registration_actor(9891)),'Global verified signup-only account included without invented edition membership');
select pg_temp.registration_settings('synthetic-announcements-other-edition');
select pg_temp.registration_fixture(9892,'synthetic-announcements-other-edition');
select pg_temp.registration_submit('synthetic-announcements-other-edition',9892,md5('9892')||md5('9892'));
select ok(not exists(select 1 from msrc_announcements.audience('synthetic-announcements') where segment='registration_pending' and actor_id=pg_temp.registration_actor(9892)),'Registration groups exclude other-edition business records');
select ok(exists(select 1 from msrc_announcements.audience('synthetic-announcements-other-edition') where segment='registration_pending' and actor_id=pg_temp.registration_actor(9892)),'Business record belongs only to its actual edition segment');
select * from finish();
rollback;
